    ["<Assistant_Title1>Eternal Challenge</>\n<Assistant_Title2>Achievement Category: </>Battle for Growth - Competition\n<Assistant_Title2>Unlock Condition: </>Complete 100 rounds of Dominator's Clash"] = "\\u003cAssistant_Title1\\u003eВечный вызов\\u003c/\\u003e\n\\u003cAssistant_Title2\\u003eКатегория достижения: \\u003c/\\u003eВоенное развитие — Состязания\n\\u003cAssistant_Title2\\u003eУсловие получения: \\u003c/\\u003eЗавершите 100 матчей в «Битве Владык»",
